const codes = {
    EPERM: -1,
    ENOENT: -2,
    EINTR: -4,
    EAGAIN: -11,
    EACCESS: -13,
    EFAULT: -14,
    ENOTSOCK: -88,
    EPROTOTYPE: -91,
    EADDRINUSE: -98,
    EISCONN: -106,
    ENOTCONN: -107,
    ETIMEDOUT: -110,
    ECONNREFUSED: -111,
    EALREADY: -114,
    EINPROGRESS: -115,
};
const codesMap = new Map(Object.keys(codes).map(key => [codes[key], key]));

function normalizeError(error) {
    if (error && error.code && codesMap.has(error.code)) {
        error.message = `${codesMap.get(error.code)}: ${error.message}`;
    }
    return error;
}

module.exports = {
    codes,
    normalizeError,
};
